INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(448159, 42000, 772, '<td valign="top">Well done photo... the lighting is creating some interest, but the overall subject choice doesn''t particularly interest me.  The sharpness also seems to fade off a bit towards the right side of the image.  I can''t see any particular benefit to not having this entire photo in focus.</td>', 'Well done photo... the lighting is creating some interest, but the overall subject choice doesn''t particularly interest me.  The sharpness also seems to fade off a bit towards the right side of the image.  I can''t see any particular benefit to not having this entire photo in focus.', '2003-10-13 01:04:25.000000', NULL, 1),
(448162, 42013, 772, '<td valign="top">Interesting compisition.  The textures here are quite nice.  This photo could possibly make an interesting black and white as well.</td>', 'Interesting compisition.  The textures here are quite nice.  This photo could possibly make an interesting black and white as well.', '2003-10-13 01:05:54.000000', NULL, 1),
(448164, 41400, 772, '<td valign="top">Good job using lighting to create some extra effect on this macro.  The detail here is excellent.  When working with macros, you have to pay extra close attention to the finer detail like that small spot just off the left edge of the top shadow.  It''s a minor thing but it shows up with more strength in a closeup photo.</td>', 'Good job using lighting to create some extra effect on this macro.  The detail here is excellent.  When working with macros, you have to pay extra close attention to the finer detail like that small spot just off the left edge of the top shadow.  It''s a minor thing but it shows up with more strength in a closeup photo.', '2003-10-13 01:08:22.000000', NULL, 1),
(448167, 41461, 772, '<td valign="top">Good use of shallow depth of field here to isolate your subject.  I don''t know if it was possible or not, but recomposing to include the entire burgandy part of this gate part could have been nice.  Not knowing what''s below that makes it difficult to suggest :)</td>', 'Good use of shallow depth of field here to isolate your subject.  I don''t know if it was possible or not, but recomposing to include the entire burgandy part of this gate part could have been nice.  Not knowing what''s below that makes it difficult to suggest :)', '2003-10-13 01:10:27.000000', NULL, 1),
(448169, 42023, 10625, '<td valign="top">LoL<br/></td>', 'LoL', '2003-10-13 01:10:46.000000', NULL, 1),
(448173, 41964, 10414, '<td valign="top">Beautiful!!  Colors are wonderful and vibrant! :)</td>', 'Beautiful!!  Colors are wonderful and vibrant! :)', '2003-10-13 01:12:00.000000', NULL, 1),
(448174, 41411, 772, '<td valign="top">The subject choice here is quite interesting.  The overall compositoin feels a bit flat though.  Maybe some creative lighting or a different angle on the shot would help improve that somewhat.  Composing on a smaller part of this scene to bring out that detail could also be an interesting improvement.</td>', 'The subject choice here is quite interesting.  The overall compositoin feels a bit flat though.  Maybe some creative lighting or a different angle on the shot would help improve that somewhat.  Composing on a smaller part of this scene to bring out that detail could also be an interesting improvement.', '2003-10-13 01:12:03.000000', NULL, 1),
(448182, 42030, 7350, '<td valign="top">Even in Black and White, I can tell this is a Sidwell girl.  There are lots of things I really like about this shot.  I''ll start with those:<br/>First, the details of the setup.<br/>1.  Her hair is not perfectly "coiffed."  That sets the feeling of the "world" being unfriendly at times.<br/>2.  The hole in her jeans.  As above.<br/>3.  Barefoot.  As above.<br/>4.  Slight frown.  As above.<br/> <br/>Next, the composition<br/>1.  I like the centered subject.  Works perfectly here. <br/> <br/>Details of the shot:<br/>1.  I think that having her shirt washed out like that really blends it in with the border.<br/>2.  Also, the varying textures on the sidewalk around her really frames her nicely.<br/> <br/>I think that one thing to try would have been having the entire square she''s sitting in be in the shot, but her still in the center of the frame.  I''m not sure that would have been better, because I can''t picture it in my head too well, but it could be something to try, anyway.<br/> <br/>Also, perhaps just slightly thinner on the border?<br/> <br/>Overall, I really love this shot.  10 from me.</td>', 'Even in Black and White, I can tell this is a Sidwell girl.  There are lots of things I really like about this shot.  I''ll start with those:First, the details of the setup.1.  Her hair is not perfectly "coiffed."  That sets the feeling of the "world" being unfriendly at times.2.  The hole in her jeans.  As above.3.  Barefoot.  As above.4.  Slight frown.  As above. Next, the composition1.  I like the centered subject.  Works perfectly here.  Details of the shot:1.  I think that having her shirt washed out like that really blends it in with the border.2.  Also, the varying textures on the sidewalk around her really frames her nicely. I think that one thing to try would have been having the entire square she''s sitting in be in the shot, but her still in the center of the frame.  I''m not sure that would have been better, because I can''t picture it in my head too well, but it could be something to try, anyway. Also, perhaps just slightly thinner on the border? Overall, I really love this shot.  10 from me.', '2003-10-13 01:14:03.000000', NULL, 1),
(448183, 42008, 7350, '<td valign="top">I love the carved eyes - really reafirm the fact that this jack-o-lantern is vomiting.  I do think the color could be just a little brighter on the oranges, to make it "pop" a little more.  Also, maybe trying to adjust the lighting to get rid of some of that shadow.  It''s a little distracting.  Seriously, I love the idea and the composition.  7.</td>', 'I love the carved eyes - really reafirm the fact that this jack-o-lantern is vomiting.  I do think the color could be just a little brighter on the oranges, to make it "pop" a little more.  Also, maybe trying to adjust the lighting to get rid of some of that shadow.  It''s a little distracting.  Seriously, I love the idea and the composition.  7.', '2003-10-13 01:16:31.000000', NULL, 1),
(448186, 41952, 10720, '<td valign="top">Well done picture. Really like the colors and the lines.</td>', 'Well done picture. Really like the colors and the lines.', '2003-10-13 01:17:33.000000', NULL, 1),
(448188, 41952, 8624, '<td valign="top">very clever and crisply composed</td>', 'very clever and crisply composed', '2003-10-13 01:18:07.000000', NULL, 1),
(448191, 41842, 7350, '<td valign="top">I like the blur on the flowers.  Well done.</td>', 'I like the blur on the flowers.  Well done.', '2003-10-13 01:19:17.000000', NULL, 1),
(448192, 42011, 7504, '<td valign="top">This works for me, the photographer, usually hidden, is revealed here and the tree reveals her fall colors.  Besides that it''s just downright beautiful!</td>', 'This works for me, the photographer, usually hidden, is revealed here and the tree reveals her fall colors.  Besides that it''s just downright beautiful!', '2003-10-13 01:20:01.000000', NULL, 1),
(448201, 41380, 8624, '<td valign="top">nice composition and good idea, but the printing on the film roll is not very sharp.</td>', 'nice composition and good idea, but the printing on the film roll is not very sharp.', '2003-10-13 01:25:32.000000', NULL, 1),
(448204, 41900, 8624, '<td valign="top">well seen. a clever take on the challenge</td>', 'well seen. a clever take on the challenge', '2003-10-13 01:26:51.000000', NULL, 1),
(448208, 41440, 8624, '<td valign="top">good contrast against the black background, but a strange choice in cropping. why did you cut off the fruit at the bottom of the frame like that?</td>', 'good contrast against the black background, but a strange choice in cropping. why did you cut off the fruit at the bottom of the frame like that?', '2003-10-13 01:28:32.000000', NULL, 1),
(448209, 41974, 12448, '<td valign="top">Nice find!  They are hard to find, I know, when I did a project for the Pre-School hour I had to go to a fish store, couldn''t find them in my garden!  At first the grass in the front is a bit distracting but upon looking more it does add to the shot giving the sense of hiding to start with.  I''m giving you a 7 to start but it may go up as I come back again.</td>', 'Nice find!  They are hard to find, I know, when I did a project for the Pre-School hour I had to go to a fish store, couldn''t find them in my garden!  At first the grass in the front is a bit distracting but upon looking more it does add to the shot giving the sense of hiding to start with.  I''m giving you a 7 to start but it may go up as I come back again.', '2003-10-13 01:28:57.000000', NULL, 1),
(448212, 42008, 10084, '<td valign="top">After looking at all the entries I find this to be the coolest entry. Love the creativity you use in this shot. Lighting helps to give a great shadow in the eye of the jack o''lantern. The way that the carved pumpkins eye appears gives it a great mood. The seeds mix with the orange of the pulp nicely and gives the shot a good interest. Very vibrant colors.</td>', 'After looking at all the entries I find this to be the coolest entry. Love the creativity you use in this shot. Lighting helps to give a great shadow in the eye of the jack o''lantern. The way that the carved pumpkins eye appears gives it a great mood. The seeds mix with the orange of the pulp nicely and gives the shot a good interest. Very vibrant colors.', '2003-10-13 01:32:06.000000', NULL, 1),
(448213, 41970, 12448, '<td valign="top">Very nice, tastefully done and would seem to fit the challenge but with the rash of thongs in the world, is it really something that was concealed to start with? :)  Just kidding, very nice shot, well done, the lighting is very well done.  I''m starting with a 7, may go higher before we are done.</td>', 'Very nice, tastefully done and would seem to fit the challenge but with the rash of thongs in the world, is it really something that was concealed to start with? :)  Just kidding, very nice shot, well done, the lighting is very well done.  I''m starting with a 7, may go higher before we are done.', '2003-10-13 01:32:34.000000', NULL, 1),
(448214, 41960, 8624, '<td valign="top">unique angle on a banana shot.  I like the curve coming in from the top left of the frame and the exposed textures of the peel..</td>', 'unique angle on a banana shot.  I like the curve coming in from the top left of the frame and the exposed textures of the peel..', '2003-10-13 01:32:57.000000', NULL, 1),
(448220, 41980, 12448, '<td valign="top">I''m betting this is for doughnuts!!!!!!!!  A wonderful idea and the overall shot is well done.  The cropping is great, the whisk''s angle draws your eyes from right to left while the writing takes you left to right.  The few fuzzy wires are a bit distracting and could be just a tad sharper and lighter.  Starting with a 7, may go higher.</td>', 'I''m betting this is for doughnuts!!!!!!!!  A wonderful idea and the overall shot is well done.  The cropping is great, the whisk''s angle draws your eyes from right to left while the writing takes you left to right.  The few fuzzy wires are a bit distracting and could be just a tad sharper and lighter.  Starting with a 7, may go higher.', '2003-10-13 01:36:51.000000', NULL, 1),
(448222, 41996, 12448, '<td valign="top">Those look like black walnuts!  I know because my MIL''s old house had a tree in the back and we had to clean those damn things up every other year, LOL!  This is a great idea, the colors are fantastic and the cropping is wonderful.  My first 9, may end up a 10 for me.</td>', 'Those look like black walnuts!  I know because my MIL''s old house had a tree in the back and we had to clean those damn things up every other year, LOL!  This is a great idea, the colors are fantastic and the cropping is wonderful.  My first 9, may end up a 10 for me.', '2003-10-13 01:37:48.000000', NULL, 1),
(448225, 42008, 1717, '<td valign="top">LOL!  ew ew ew!  too funny...good work!</td>', 'LOL!  ew ew ew!  too funny...good work!', '2003-10-13 01:38:44.000000', NULL, 1),
(448226, 42013, 12448, '<td valign="top">OMG, TOO CUTE!  I just want to tickle them and massage them!  They are so cute, the lighting is wonderful and the cropping is close to perfect.  Well done, hidden for 9 months and finally exposed!  You get a 9, may be a 10 before we are done! ;)</td>', 'OMG, TOO CUTE!  I just want to tickle them and massage them!  They are so cute, the lighting is wonderful and the cropping is close to perfect.  Well done, hidden for 9 months and finally exposed!  You get a 9, may be a 10 before we are done! ;)', '2003-10-13 01:38:48.000000', NULL, 1),
(448229, 41900, 12448, '<td valign="top">Ah, construction, my father was a carpenter and the house is naked at first, inside and out.  Wonderful concept, the lighting couldn''t be much better, such a beautiful sunny day and the cropping is close to perfect.  You get an 8, may go higher before we are done.</td>', 'Ah, construction, my father was a carpenter and the house is naked at first, inside and out.  Wonderful concept, the lighting couldn''t be much better, such a beautiful sunny day and the cropping is close to perfect.  You get an 8, may go higher before we are done.', '2003-10-13 01:40:03.000000', NULL, 1),
(448230, 42023, 6668, '<td valign="top">LOL...This is hilarious!!</td>', 'LOL...This is hilarious!!', '2003-10-13 01:40:25.000000', NULL, 1),
(448231, 42016, 12448, '<td valign="top">I almost did this same thing, LOL!  So of course I love the idea and the colors are wonderful, very much this time of year, the only thing I would have done is focused more on one tree, maybe gotten closer and came from below.  Starting you with a 6, will be back to assess again.</td>', 'I almost did this same thing, LOL!  So of course I love the idea and the colors are wonderful, very much this time of year, the only thing I would have done is focused more on one tree, maybe gotten closer and came from below.  Starting you with a 6, will be back to assess again.', '2003-10-13 01:41:33.000000', NULL, 1),
(448232, 41830, 8624, '<td valign="top">a darker surface with less distracting texture than this napkin might have helped to bring out the interesting shapes in the shards of glass</td>', 'a darker surface with less distracting texture than this napkin might have helped to bring out the interesting shapes in the shards of glass', '2003-10-13 01:41:55.000000', NULL, 1),
(448233, 41818, 12448, '<td valign="top">LOL!  In the thumbnail you really can''t tell what this is and it makes you wonder!  This is a wonderful shot, the lighting, the colors, the cropping.  My first 10 of the challenge.  WELL DONE!</td>', 'LOL!  In the thumbnail you really can''t tell what this is and it makes you wonder!  This is a wonderful shot, the lighting, the colors, the cropping.  My first 10 of the challenge.  WELL DONE!', '2003-10-13 01:42:26.000000', NULL, 1),
(448234, 41952, 10084, '<td valign="top">Very vibrant colors. Love the beautiful line that is opened up to reveal the blue and red paint cans. The framing works will with the shot. This would make for a great advertising for a paint brand.</td>', 'Very vibrant colors. Love the beautiful line that is opened up to reveal the blue and red paint cans. The framing works will with the shot. This would make for a great advertising for a paint brand.', '2003-10-13 01:42:37.000000', NULL, 1),
(448235, 41175, 8624, '<td valign="top">the best of the many hard drive shots. I like your composition and cropping here. excellent lighting as well makes this one stand out from the rest</td>', 'the best of the many hard drive shots. I like your composition and cropping here. excellent lighting as well makes this one stand out from the rest', '2003-10-13 01:43:06.000000', NULL, 1),
(448236, 41461, 12448, '<td valign="top">Wonderful Idea and I think it might have worked even better if the missing paint wasn''t quite so uniform and you couldn''t see the other one just like it on the right.  Maybe if it was more head on and you could see the entire knob or whatever it is.  Starting with a 5, will be back to check and look again.</td>', 'Wonderful Idea and I think it might have worked even better if the missing paint wasn''t quite so uniform and you couldn''t see the other one just like it on the right.  Maybe if it was more head on and you could see the entire knob or whatever it is.  Starting with a 5, will be back to check and look again.', '2003-10-13 01:44:18.000000', NULL, 1),
(448237, 41959, 12448, '<td valign="top">Excellent idea!  I love it!  As for the picture itself, the colors are wonderful, I really like the mirror but the lighting seems just a bit off to me, the slice seems over lit while the main fruit is under lit.  Starting with a 6, will be back and probably go higher.</td>', 'Excellent idea!  I love it!  As for the picture itself, the colors are wonderful, I really like the mirror but the lighting seems just a bit off to me, the slice seems over lit while the main fruit is under lit.  Starting with a 6, will be back and probably go higher.', '2003-10-13 01:45:45.000000', NULL, 1),
(448239, 41772, 10084, '<td valign="top">Very vibrant yellow in the film. The shadows and reflections of the highlight in the main subject is very sharp. The reflection of the film on the tabletop is beautiful and helps to add more interest to the piece. Lighting is absolutely incredible. Black background really helps to bring the subject out. This would be a great advertisement for using digital cameras.</td>', 'Very vibrant yellow in the film. The shadows and reflections of the highlight in the main subject is very sharp. The reflection of the film on the tabletop is beautiful and helps to add more interest to the piece. Lighting is absolutely incredible. Black background really helps to bring the subject out. This would be a great advertisement for using digital cameras.', '2003-10-13 01:45:59.000000', NULL, 1),
(448241, 41400, 12448, '<td valign="top">My kids love taking the tops off the acorns and then gluing them back on, LOL, go figure!  Great idea, the shadow on the top is wonderful, it draws you into the picture.  It does seem just a bit oversharp to me, starting with an 8, will be back to look again.</td>', 'My kids love taking the tops off the acorns and then gluing them back on, LOL, go figure!  Great idea, the shadow on the top is wonderful, it draws you into the picture.  It does seem just a bit oversharp to me, starting with an 8, will be back to look again.', '2003-10-13 01:47:21.000000', NULL, 1),
(448242, 41618, 10084, '<td valign="top">Very good contrast in the piece. The vibrant shadows in the folds of the gentlemens clothes really help to draw your attention to him. The expression on his face makes you wonder about his story. Beautiful captured.</td>', 'Very good contrast in the piece. The vibrant shadows in the folds of the gentlemens clothes really help to draw your attention to him. The expression on his face makes you wonder about his story. Beautiful captured.', '2003-10-13 01:47:33.000000', NULL, 1),
(448244, 41994, 12448, '<td valign="top">Exposing your heart!  How sweet!  The idea is great but I think it would have been better with a heart on the sleeve concept.  The smile on the face says it all, the shot is a bit busy with all the grass and such and the hand almost gets lost on the horizon.  Starting with a 5, will be back.</td>', 'Exposing your heart!  How sweet!  The idea is great but I think it would have been better with a heart on the sleeve concept.  The smile on the face says it all, the shot is a bit busy with all the grass and such and the hand almost gets lost on the horizon.  Starting with a 5, will be back.', '2003-10-13 01:48:33.000000', NULL, 1),
(448245, 42004, 6668, '<td valign="top">I don''t get it...</td>', 'I don''t get it...', '2003-10-13 01:49:10.000000', NULL, 1),
(448247, 41849, 12448, '<td valign="top">Not quite exposed, but just about, heh?  Great concept and the softness adds to the shot for the box and the light but the hands almost look too soft, a bit unreal.  Starting with a 7, will be back.</td>', 'Not quite exposed, but just about, heh?  Great concept and the softness adds to the shot for the box and the light but the hands almost look too soft, a bit unreal.  Starting with a 7, will be back.', '2003-10-13 01:49:40.000000', NULL, 1),
(448248, 41948, 9441, '<td valign="top">cool photo...interesting light effect and colors.</td>', 'cool photo...interesting light effect and colors.', '2003-10-13 01:51:25.000000', NULL, 1),
(448249, 41973, 12448, '<td valign="top">Yes they are!  Hope you didn''t lose any! ;)  Going through the thumbnails this was a popular theme it would seem.  The dust or black specks are really distracting, if it had been cleaned before taking the shot it would have started with a much higher score.  I like the angle the shot was taken at and the black and white effect is perfect for this shot.  Starting with a 7, will be back.</td>', 'Yes they are!  Hope you didn''t lose any! ;)  Going through the thumbnails this was a popular theme it would seem.  The dust or black specks are really distracting, if it had been cleaned before taking the shot it would have started with a much higher score.  I like the angle the shot was taken at and the black and white effect is perfect for this shot.  Starting with a 7, will be back.', '2003-10-13 01:52:51.000000', NULL, 1),
(448250, 41952, 9441, '<td valign="top">nice, bright, vivid and sharp.  Good job.  a 10 from me.</td>', 'nice, bright, vivid and sharp.  Good job.  a 10 from me.', '2003-10-13 01:52:53.000000', NULL, 1),
(448251, 41618, 6668, '<td valign="top">I''m not quite sure how this fits the challenge, but I love the shot anyway! Very touching photo...8</td>', 'I''m not quite sure how this fits the challenge, but I love the shot anyway! Very touching photo...8', '2003-10-13 01:53:45.000000', NULL, 1),
(448253, 42042, 10673, '<td valign="top">Absolutely excellent!  10</td>', 'Absolutely excellent!  10', '2003-10-13 01:55:40.000000', NULL, 1),
