(448261, 42023, 11769, '<td valign="top">This really made me laugh. What a setup if I ever heard one! SURE. 10</td>', 'This really made me laugh. What a setup if I ever heard one! SURE. 10', '2003-10-13 02:02:20.000000', NULL, 1),
