(448718, 41772, 7263, '<td valign="top">Good Points:love the reflection, good use of mirror shot.<br/>Bad Points:not enough light on the film, which is supposed to be the main subject? (exposed) also not the most original idea. But a nice shoot nevertheless<br/>Score:6</td>', 'Good Points:love the reflection, good use of mirror shot.Bad Points:not enough light on the film, which is supposed to be the main subject? (exposed) also not the most original idea. But a nice shoot neverthelessScore:6', '2003-10-13 11:04:43.000000', NULL, 1),
(448721, 41461, 10686, '<td valign="top">There are some wonderful tones and textures here, but, I wish the ungilded part was not cropped off at the bottom.</td>', 'There are some wonderful tones and textures here, but, I wish the ungilded part was not cropped off at the bottom.', '2003-10-13 11:05:53.000000', NULL, 1),
(448722, 41717, 7263, '<td valign="top">Good Points:Like the low angle and viewpoint<br/>Bad Points:quite a dull subject -tree. Not so fitting for the challenge really as trees are not that often hidden.<br/>Score:3</td>', 'Good Points:Like the low angle and viewpointBad Points:quite a dull subject -tree. Not so fitting for the challenge really as trees are not that often hidden.Score:3', '2003-10-13 11:05:57.000000', NULL, 1),
(448723, 41441, 8522, '<td valign="top">Maybe I''m being picky, but I don''t see autumnal colours as having been concealed. They didn''t exist. This photo is so oversaturated, it hurts my eyes to look at it! 3</td>', 'Maybe I''m being picky, but I don''t see autumnal colours as having been concealed. They didn''t exist. This photo is so oversaturated, it hurts my eyes to look at it! 3', '2003-10-13 11:07:04.000000', NULL, 1),
(448724, 41849, 7263, '<td valign="top">Good Points:idea is fantastic, well lit<br/>Bad Points: composition could be better, much better. quite an unexciting angle really. perhaps lower or straighter - i''m not sure just something amiss about it all.<br/>Score:6</td>', 'Good Points:idea is fantastic, well litBad Points: composition could be better, much better. quite an unexciting angle really. perhaps lower or straighter - i''m not sure just something amiss about it all.Score:6', '2003-10-13 11:07:29.000000', NULL, 1),
(448725, 41533, 7263, '<td valign="top">Good Points:good choice of flower - very different<br/>Bad Points:looks clumsy, and 2 colors don''t work (blue and black)<br/>Score:3</td>', 'Good Points:good choice of flower - very differentBad Points:looks clumsy, and 2 colors don''t work (blue and black)Score:3', '2003-10-13 11:08:16.000000', NULL, 1),
(448726, 41970, 10686, '<td valign="top">I like the form and the composition, but I can''t decide if I like the darker skin tones, it seems like it should be just a bit brighter. Oh well. Still worth a high score from me</td>', 'I like the form and the composition, but I can''t decide if I like the darker skin tones, it seems like it should be just a bit brighter. Oh well. Still worth a high score from me', '2003-10-13 11:09:38.000000', NULL, 1),
(448727, 42011, 10686, '<td valign="top">That''s funny</td>', 'That''s funny', '2003-10-13 11:10:24.000000', NULL, 1),
(448728, 41731, 7263, '<td valign="top">Good Points:Lighting is superb and so is the viewpoint.<br/>Bad Points:not really meeting the challenge I feel unless the spire is normally under wraps. as a photo i love it  it''s a 9<br/>Score:3</td>', 'Good Points:Lighting is superb and so is the viewpoint.Bad Points:not really meeting the challenge I feel unless the spire is normally under wraps. as a photo i love it  it''s a 9Score:3', '2003-10-13 11:10:42.000000', NULL, 1),
(448730, 41747, 7263, '<td valign="top">Good Points:clarity idea and execution great!!!<br/>Bad Points: a bit too much light reflecting on the left strap but that''s clutching at straws for a bad point ;)<br/>Score:9</td>', 'Good Points:clarity idea and execution great!!!Bad Points: a bit too much light reflecting on the left strap but that''s clutching at straws for a bad point ;)Score:9', '2003-10-13 11:12:04.000000', NULL, 1),
(448731, 42014, 7263, '<td valign="top">Good Points: interesting building/subject good colours and textures<br/>Bad Points:not really fitting the challenge and the top right tree is a distraction<br/>Score:2</td>', 'Good Points: interesting building/subject good colours and texturesBad Points:not really fitting the challenge and the top right tree is a distractionScore:2', '2003-10-13 11:13:21.000000', NULL, 1),
(448732, 41953, 10686, '<td valign="top">I like the lighting and the B&amp;W. I think it might be stronger graphically if it were cropped as a vertical. The hands seem to be covering something, not exposing it, but that''s just my nitpick.</td>', 'I like the lighting and the B&W. I think it might be stronger graphically if it were cropped as a vertical. The hands seem to be covering something, not exposing it, but that''s just my nitpick.', '2003-10-13 11:14:16.000000', NULL, 1),
(448734, 41991, 7263, '<td valign="top">Good Points:like the way it''s lit, very different, and good focus on the cylinder part<br/>Bad Points:a bit unoriginal, seen about 10 of thse allready.<br/>Score:6</td>', 'Good Points:like the way it''s lit, very different, and good focus on the cylinder partBad Points:a bit unoriginal, seen about 10 of thse allready.Score:6', '2003-10-13 11:14:25.000000', NULL, 1),
(448735, 41874, 10686, '<td valign="top">BUSTED!!</td>', 'BUSTED!!', '2003-10-13 11:14:34.000000', NULL, 1),
(448736, 41966, 7263, '<td valign="top">Good Points:nice and clear, good color repro''<br/>Bad Points:border is not nice and uneeded (orange color) fairly uninspiring overall.<br/>Score:5</td>', 'Good Points:nice and clear, good color repro''Bad Points:border is not nice and uneeded (orange color) fairly uninspiring overall.Score:5', '2003-10-13 11:15:24.000000', NULL, 1),
(448737, 41962, 7263, '<td valign="top">Good Points:quite like the composition and colors<br/>Bad Points:reflections are distracting, and could be a touch sharper on the chocolate. border really ruins this.<br/>Score:5</td>', 'Good Points:quite like the composition and colorsBad Points:reflections are distracting, and could be a touch sharper on the chocolate. border really ruins this.Score:5', '2003-10-13 11:16:44.000000', NULL, 1),
(448738, 41950, 7263, '<td valign="top">Good Points:very good subject matter and composition<br/>Bad Points:looks ever so slightly dull, a touch-up with levels to give some highlights - all seems a bit flat. also your image is too small.<br/>Score:</td>', 'Good Points:very good subject matter and compositionBad Points:looks ever so slightly dull, a touch-up with levels to give some highlights - all seems a bit flat. also your image is too small.Score:', '2003-10-13 11:18:01.000000', NULL, 1),
(448739, 41900, 7263, '<td valign="top">Good Points:see your idea and like it.<br/>Bad Points:overall it makes for a dull photograph. no interesting focal points of detail or color.<br/>Score:3</td>', 'Good Points:see your idea and like it.Bad Points:overall it makes for a dull photograph. no interesting focal points of detail or color.Score:3', '2003-10-13 11:19:09.000000', NULL, 1),
(448740, 41957, 7263, '<td valign="top">Good Points:closeness and composition are pretty good<br/>Bad Points: not the most original idea and would have been better if dusted beforehand.<br/>Score:4</td>', 'Good Points:closeness and composition are pretty goodBad Points: not the most original idea and would have been better if dusted beforehand.Score:4', '2003-10-13 11:20:15.000000', NULL, 1),
(448743, 42030, 7263, '<td valign="top">Good Points: good symetrics (sp)<br/>Bad Points: doesn''t meet challenge - unless she is normally covered in something?NOT a snapshot mind you ;)</td>', 'Good Points: good symetrics (sp)Bad Points: doesn''t meet challenge - unless she is normally covered in something?NOT a snapshot mind you ;)', '2003-10-13 11:26:32.000000', NULL, 1),
(448744, 41067, 5475, '<td valign="top">This gets a 10 from me!  The simple elegance of this shot is wonderful.  The negative space really caught my attention, then the pattern of the veins in the leaf compliment the shape of the leaf nicely.  Well done!<br/>JD Anderson</td>', 'This gets a 10 from me!  The simple elegance of this shot is wonderful.  The negative space really caught my attention, then the pattern of the veins in the leaf compliment the shape of the leaf nicely.  Well done!JD Anderson', '2003-10-13 11:27:24.000000', NULL, 1),
(448746, 41172, 5475, '<td valign="top">10 from me!  The ''key'' to so many things in life!  Great job.<br/>JD Anderson</td>', '10 from me!  The ''key'' to so many things in life!  Great job.JD Anderson', '2003-10-13 11:28:08.000000', NULL, 1),
(448749, 42026, 12617, '<td valign="top">just personal prefrence, I would''ve preferred to see the closest tooth in focus, and the rest blur out.</td>', 'just personal prefrence, I would''ve preferred to see the closest tooth in focus, and the rest blur out.', '2003-10-13 11:34:46.000000', NULL, 1),
(448751, 42041, 12617, '<td valign="top">sorry, but I think I''m missing something in this photo.<br/>eitherway, not a bad photo, the shadow''s a bit dark, and I woulda ripped it out of the case  and given it a uniform background.. or cropped it differently, just personal prefrence.</td>', 'sorry, but I think I''m missing something in this photo.eitherway, not a bad photo, the shadow''s a bit dark, and I woulda ripped it out of the case  and given it a uniform background.. or cropped it differently, just personal prefrence.', '2003-10-13 11:46:04.000000', NULL, 1),
(448756, 42041, 10414, '<td valign="top">Computer innards!!!!   :)   I love it!!  10</td>', 'Computer innards!!!!   :)   I love it!!  10', '2003-10-13 12:03:56.000000', NULL, 1),
(448757, 41618, 327, '<td valign="top">The photograph is fantastic-clean, clean, and great tones. I see poverty exposed here. Wonderful work.</td>', 'The photograph is fantastic-clean, clean, and great tones. I see poverty exposed here. Wonderful work.', '2003-10-13 12:05:10.000000', NULL, 1),
(448758, 42029, 327, '<td valign="top">Nice photo. Wee bit dark [on the butterfly] but I love the aperture you used. This is very fitting to the challenge. Nice job.</td>', 'Nice photo. Wee bit dark [on the butterfly] but I love the aperture you used. This is very fitting to the challenge. Nice job.', '2003-10-13 12:06:38.000000', NULL, 1),
(448760, 42036, 327, '<td valign="top">Shocking, sad..but very good for our challenge. I think your idea here was excellent. I might of changed the composition a bit to remove so much of the whiteness at the bottom. Still that is minor and would of tilted the whole shot...You did well.</td>', 'Shocking, sad..but very good for our challenge. I think your idea here was excellent. I might of changed the composition a bit to remove so much of the whiteness at the bottom. Still that is minor and would of tilted the whole shot...You did well.', '2003-10-13 12:08:32.000000', NULL, 1),
(448762, 42009, 327, '<td valign="top">Very good idea for the challenge. I do think the focus should of been a more on the inner workings of the drive. Broader dof, but I do like this and think you met the challenge.</td>', 'Very good idea for the challenge. I do think the focus should of been a more on the inner workings of the drive. Broader dof, but I do like this and think you met the challenge.', '2003-10-13 12:09:58.000000', NULL, 1),
(448763, 41959, 772, '<td valign="top">Good composition and nice lighting as well.  I like the mirror idea as a surface.  Nice work :)</td>', 'Good composition and nice lighting as well.  I like the mirror idea as a surface.  Nice work :)', '2003-10-13 12:11:02.000000', NULL, 1),
(448764, 42025, 327, '<td valign="top">The lighting is good/bad. A few areas look over sharpened or fried. However the top portion of the pepper where the seeds are look great. Your composition is very good, as is the framing and color. Spot on for the challenge also.</td>', 'The lighting is good/bad. A few areas look over sharpened or fried. However the top portion of the pepper where the seeds are look great. Your composition is very good, as is the framing and color. Spot on for the challenge also.', '2003-10-13 12:11:55.000000', NULL, 1),
(448765, 42020, 772, '<td valign="top">You did a good job of creating a ''dark'' background in this shot.  I think a lighter background would create a better contrast with the dark colors of your subject and help bring out the detail more.  It looks like it''s floating in space with no visible surface.</td>', 'You did a good job of creating a ''dark'' background in this shot.  I think a lighter background would create a better contrast with the dark colors of your subject and help bring out the detail more.  It looks like it''s floating in space with no visible surface.', '2003-10-13 12:12:33.000000', NULL, 1),
(448766, 41849, 772, '<td valign="top">Interesting abstract and creative use of light :)</td>', 'Interesting abstract and creative use of light :)', '2003-10-13 12:13:15.000000', NULL, 1),
(448767, 41859, 327, '<td valign="top">Exposed...? Okay I can kind of see it. Beyond the challenge idea, I like this shot very much. It has a good mood/feeling and colors. The focus is very nice also. I don''t like the bottom tilted and the left hand crop.</td>', 'Exposed...? Okay I can kind of see it. Beyond the challenge idea, I like this shot very much. It has a good mood/feeling and colors. The focus is very nice also. I don''t like the bottom tilted and the left hand crop.', '2003-10-13 12:13:48.000000', NULL, 1),
(448768, 41532, 7263, '<td valign="top">Good points: nice colours and great composition<br/>Bad Points: none - but the border is a bit too thick for my taste.<br/>Score:8</td>', 'Good points: nice colours and great compositionBad Points: none - but the border is a bit too thick for my taste.Score:8', '2003-10-13 12:13:58.000000', NULL, 1),
(448769, 42030, 772, '<td valign="top">This is a beautiful shot.  I love the color tone choice because it does relay a sense of ''cold'' in this image.  I think the centered composition also works with a lot of strength here.  Excellent work... = 10</td>', 'This is a beautiful shot.  I love the color tone choice because it does relay a sense of ''cold'' in this image.  I think the centered composition also works with a lot of strength here.  Excellent work... = 10', '2003-10-13 12:14:21.000000', NULL, 1),
(448770, 41858, 327, '<td valign="top">Where is the center of your focus here?  To my eye everything appears a little out of focus. The light is so strong it''s harsh on the drops of water. Beyond that you have met the challenge and the shot is interesting to look at.</td>', 'Where is the center of your focus here?  To my eye everything appears a little out of focus. The light is so strong it''s harsh on the drops of water. Beyond that you have met the challenge and the shot is interesting to look at.', '2003-10-13 12:16:00.000000', NULL, 1),
(448771, 41958, 772, '<td valign="top">Beautiful shot.  This is one of the best still life images I have seen here recently.  I particularly like the way the lighting highlights the ''1923'' on the wine bottle.  I''m no wine afficianado, but would this old wine be turned to vinegar by now?  Beautiful work and excellent composition overall... = 10</td>', 'Beautiful shot.  This is one of the best still life images I have seen here recently.  I particularly like the way the lighting highlights the ''1923'' on the wine bottle.  I''m no wine afficianado, but would this old wine be turned to vinegar by now?  Beautiful work and excellent composition overall... = 10', '2003-10-13 12:16:03.000000', NULL, 1),
(448772, 41589, 772, '<td valign="top">I think you have a strong subject choice here, but the overall composition seems to be a bit lacking.  The tonal range seems a bit flat and the yellow tint could be contributing to that.</td>', 'I think you have a strong subject choice here, but the overall composition seems to be a bit lacking.  The tonal range seems a bit flat and the yellow tint could be contributing to that.', '2003-10-13 12:17:08.000000', NULL, 1),
(448773, 41818, 327, '<td valign="top">Nice shooting. Challenge met. Good focus, light and colors. The only change would of been the one [right side] blade of grass. I know you didn''t plant this, just took the photo. It''s a nice shot.</td>', 'Nice shooting. Challenge met. Good focus, light and colors. The only change would of been the one [right side] blade of grass. I know you didn''t plant this, just took the photo. It''s a nice shot.', '2003-10-13 12:17:30.000000', NULL, 1),
(448774, 42031, 327, '<td valign="top">I see what you were doing in this shot and I think your idea is good. It''s the composition that is lacking here. The top is dead space and unless you see the mirror you wouldn''t know this was a car. You did meet the challenge and the color is good.......also the car is totally cool.</td>', 'I see what you were doing in this shot and I think your idea is good. It''s the composition that is lacking here. The top is dead space and unless you see the mirror you wouldn''t know this was a car. You did meet the challenge and the color is good.......also the car is totally cool.', '2003-10-13 12:19:34.000000', NULL, 1),
(448776, 41731, 772, '<td valign="top">This is a beautiful sky-scape.  Excellent work... the buildings in the lower portion of the frame provide nice ''anchoring'' for the image.</td>', 'This is a beautiful sky-scape.  Excellent work... the buildings in the lower portion of the frame provide nice ''anchoring'' for the image.', '2003-10-13 12:20:41.000000', NULL, 1),
(448778, 41972, 772, '<td valign="top">Very creative use of lighting here... I would probably like this composition more if it was cropped in tighter to remove the emptiness on both sides of your subject.  That empty space doesn''t seem to be supporting the subject in any way that I can determine.</td>', 'Very creative use of lighting here... I would probably like this composition more if it was cropped in tighter to remove the emptiness on both sides of your subject.  That empty space doesn''t seem to be supporting the subject in any way that I can determine.', '2003-10-13 12:21:51.000000', NULL, 1),
(448779, 41474, 772, '<td valign="top">Interesting idea... This photo seems a bit ''contrasty'' overall.  There is a lot of color and a lot of contrast in the overall presentation.</td>', 'Interesting idea... This photo seems a bit ''contrasty'' overall.  There is a lot of color and a lot of contrast in the overall presentation.', '2003-10-13 12:22:44.000000', NULL, 1),
(448781, 41952, 4400, '<td valign="top">Excellent!! very nice 10 pt (ribbon)</td>', 'Excellent!! very nice 10 pt (ribbon)', '2003-10-13 12:24:01.000000', NULL, 1),
(448782, 41977, 772, '<td valign="top">The color in this image is quite powerful... almost too powerful.  The presentation of the lemon seems a bit weak.  The color contrast in the image is more powerful than the subject itself.</td>', 'The color in this image is quite powerful... almost too powerful.  The presentation of the lemon seems a bit weak.  The color contrast in the image is more powerful than the subject itself.', '2003-10-13 12:24:14.000000', NULL, 1),
(448783, 42032, 327, '<td valign="top">Winning idea, spot on for the challenge. I think this falls short because of the poor lighting. The pith is white and should look less orange.  I understand the dilemma. I think the composition is very nice.</td>', 'Winning idea, spot on for the challenge. I think this falls short because of the poor lighting. The pith is white and should look less orange.  I understand the dilemma. I think the composition is very nice.', '2003-10-13 12:24:40.000000', NULL, 1),
(448784, 41576, 772, '<td valign="top">I think you could have created a double whammy on the theme of this challenge by opening up the back of the camera completely :)</td>', 'I think you could have created a double whammy on the theme of this challenge by opening up the back of the camera completely :)', '2003-10-13 12:25:13.000000', NULL, 1),
(448785, 41953, 4400, '<td valign="top">Well done 10 pt</td>', 'Well done 10 pt', '2003-10-13 12:25:13.000000', NULL, 1),
(448786, 41271, 772, '<td valign="top">Beautiful work.  I love how the light interacts with the surface of the water behind this frog.  This is also an excellent macro... great work :) = 10</td>', 'Beautiful work.  I love how the light interacts with the surface of the water behind this frog.  This is also an excellent macro... great work :) = 10', '2003-10-13 12:25:59.000000', NULL, 1),
(448787, 42033, 772, '<td valign="top">This is definitely a tough subject to photograph.  The glass or plexiglass between you and the bees is making it difficult to create strong contrast in this image.</td>', 'This is definitely a tough subject to photograph.  The glass or plexiglass between you and the bees is making it difficult to create strong contrast in this image.', '2003-10-13 12:26:48.000000', NULL, 1),
(448789, 41041, 7504, '<td valign="top">This is lovely.  Nice catch.</td>', 'This is lovely.  Nice catch.', '2003-10-13 12:39:36.000000', NULL, 1),
(448792, 41830, 7504, '<td valign="top">A different color background on this would help the light bulb to stand out more.</td>', 'A different color background on this would help the light bulb to stand out more.', '2003-10-13 12:40:40.000000', NULL, 1),
(448795, 41842, 772, '<td valign="top">Excellent composition.. the color here is lovely :)</td>', 'Excellent composition.. the color here is lovely :)', '2003-10-13 12:41:01.000000', NULL, 1),
(448796, 42039, 7504, '<td valign="top">Well, that''s nifty.</td>', 'Well, that''s nifty.', '2003-10-13 12:41:20.000000', NULL, 1),
(448797, 41818, 772, '<td valign="top">very nice work :)  good macro and nice use of shallow depth of field...</td>', 'very nice work :)  good macro and nice use of shallow depth of field...', '2003-10-13 12:42:48.000000', NULL, 1),
(448799, 42015, 7504, '<td valign="top">This seems rather oversharpened.  I like the color choices here a lot.</td>', 'This seems rather oversharpened.  I like the color choices here a lot.', '2003-10-13 12:44:05.000000', NULL, 1),
(448802, 41582, 7504, '<td valign="top">Oh, wow, this is so serene and beautiful.  I guess it''s the moon being revealed right?  Nice.</td>', 'Oh, wow, this is so serene and beautiful.  I guess it''s the moon being revealed right?  Nice.', '2003-10-13 12:45:42.000000', NULL, 1),
(448803, 41849, 7504, '<td valign="top">Very nice effect, right on for the challenge.  Excellent.</td>', 'Very nice effect, right on for the challenge.  Excellent.', '2003-10-13 12:46:18.000000', NULL, 1),
(448804, 41640, 772, '<td valign="top">Interesting idea.  I just can''t get myself enthused about the subject.</td>', 'Interesting idea.  I just can''t get myself enthused about the subject.', '2003-10-13 12:46:46.000000', NULL, 1),
(448805, 41084, 772, '<td valign="top">I think that having the unwrapped kiss off center would improve this compostion.  The overall images is a bit soft as well.</td>', 'I think that having the unwrapped kiss off center would improve this compostion.  The overall images is a bit soft as well.', '2003-10-13 12:48:09.000000', NULL, 1),
(448810, 41582, 12733, '<td valign="top">Nice sky and selection of foreground silhouette. The moon makes a nice focal point, but seems almost incidental to the overall picture.</td>', 'Nice sky and selection of foreground silhouette. The moon makes a nice focal point, but seems almost incidental to the overall picture.', '2003-10-13 12:53:53.000000', NULL, 1),
(448812, 42023, 7504, '<td valign="top">Cute idea.  Congratulations, i think?</td>', 'Cute idea.  Congratulations, i think?', '2003-10-13 12:58:11.000000', NULL, 1),
(448823, 41954, 11923, '<td valign="top">I like the concept, but I find the picture to be a tad dark.  IMO, it would add to the interest if the journal was buried a bit (either by leaves or in ground partially) and if the shot was a bit closer so you could read some of the wording clearly.</td>', 'I like the concept, but I find the picture to be a tad dark.  IMO, it would add to the interest if the journal was buried a bit (either by leaves or in ground partially) and if the shot was a bit closer so you could read some of the wording clearly.', '2003-10-13 13:09:51.000000', NULL, 1),
(448830, 41988, 327, '<td valign="top">Good idea, fun thinking. I would of liked the bottom 1/4 cropped out and maybe a little less saturation. Over all this is good, and it''s bang on for the challenge.</td>', 'Good idea, fun thinking. I would of liked the bottom 1/4 cropped out and maybe a little less saturation. Over all this is good, and it''s bang on for the challenge.', '2003-10-13 13:18:21.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(448833, 41532, 327, '<td valign="top">Humm, the shallow dof doesn''t really add to _this_ shot in my opinion. The subject is the cone yet the it''s not in focus. I''m unsure what the grey circle is in the shot?? I will say that I think your lighting is very good.</td>', 'Humm, the shallow dof doesn''t really add to _this_ shot in my opinion. The subject is the cone yet the it''s not in focus. I''m unsure what the grey circle is in the shot?? I will say that I think your lighting is very good.', '2003-10-13 13:20:52.000000', NULL, 1),
(448834, 42029, 11923, '<td valign="top">Nice photo, I wish the colors were a little more vivid, with the light coming through the wings more or something similar.  Just a bit darker than I like.   The butterfly and the broken cocoon tell a story and fit the challenge well.  6</td>', 'Nice photo, I wish the colors were a little more vivid, with the light coming through the wings more or something similar.  Just a bit darker than I like.   The butterfly and the broken cocoon tell a story and fit the challenge well.  6', '2003-10-13 13:21:29.000000', NULL, 1),
(448836, 41576, 11923, '<td valign="top">Nice photo, fits the challenge well.  I like the background, but I find the black &amp; white aspect a bit flat.  Would''ve liked all of the camera parts in the shot.  Good focus on the camera.  5</td>', 'Nice photo, fits the challenge well.  I like the background, but I find the black & white aspect a bit flat.  Would''ve liked all of the camera parts in the shot.  Good focus on the camera.  5', '2003-10-13 13:24:01.000000', NULL, 1),
