INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(449984, 41730, 11111, '<td valign="top">Great idea for this one! This was a joy to view. Really nice b&amp;w exposure. Love the expression. I''d pick this as tops.</td>', 'Great idea for this one! This was a joy to view. Really nice b&w exposure. Love the expression. I''d pick this as tops.', '2003-10-14 12:42:59.000000', NULL, 1),
(449988, 42015, 11111, '<td valign="top">Neat idea. Great colors and composition. I think it''s a bit oversharpened though.</td>', 'Neat idea. Great colors and composition. I think it''s a bit oversharpened though.', '2003-10-14 12:44:35.000000', NULL, 1),
(449991, 41980, 11111, '<td valign="top">This is really creative and I like it a lot. Particularly like the pattern created by whisk. Border seems too heavy though.</td>', 'This is really creative and I like it a lot. Particularly like the pattern created by whisk. Border seems too heavy though.', '2003-10-14 12:48:03.000000', NULL, 1),
(449993, 41818, 11111, '<td valign="top">Made me giggle. Brilliant color. Love the composition and sense of humor.</td>', 'Made me giggle. Brilliant color. Love the composition and sense of humor.', '2003-10-14 12:49:03.000000', NULL, 1),
(449994, 41958, 11111, '<td valign="top">What clever lighting! I love the dusty bottle texture that contrasts with the clarity of the wine and glass. A beautiful photo. At first I found bottles in upper right background distracting, but on second look I love the whole thing.</td>', 'What clever lighting! I love the dusty bottle texture that contrasts with the clarity of the wine and glass. A beautiful photo. At first I found bottles in upper right background distracting, but on second look I love the whole thing.', '2003-10-14 12:50:42.000000', NULL, 1),
(450001, 41992, 12247, '<td valign="top">first of all, no one cares about your tattoo<br/>secondly, it''s a really lame tattoo and third, quite a boring picture</td>', 'first of all, no one cares about your tattoosecondly, it''s a really lame tattoo and third, quite a boring picture', '2003-10-14 13:02:15.000000', NULL, 1),
(450002, 41964, 772, '<td valign="top">Good composition here but the uneven yellow gradients on the background look at bit odd.  Some of that yellow may be from the bleeding into the green of the kiwi fruit.  Maybe some white balance adjustments or software color correction would help here.</td>', 'Good composition here but the uneven yellow gradients on the background look at bit odd.  Some of that yellow may be from the bleeding into the green of the kiwi fruit.  Maybe some white balance adjustments or software color correction would help here.', '2003-10-14 13:02:41.000000', NULL, 1),
(450003, 41818, 12247, '<td valign="top">this is cool.  wonderful detail and color</td>', 'this is cool.  wonderful detail and color', '2003-10-14 13:03:01.000000', NULL, 1),
(450004, 42032, 12247, '<td valign="top">ooh this is pretty and cool</td>', 'ooh this is pretty and cool', '2003-10-14 13:03:32.000000', NULL, 1),
(450005, 42030, 12247, '<td valign="top">sad... but i like it</td>', 'sad... but i like it', '2003-10-14 13:04:06.000000', NULL, 1),
(450006, 41762, 772, '<td valign="top">I like the color in the sky in this photo.  The blue gradient is nice.  I think the composition may be just a bit cramped on the top left.  Maybe a little extra ''breathing room'' for the architecture would be nice here :)</td>', 'I like the color in the sky in this photo.  The blue gradient is nice.  I think the composition may be just a bit cramped on the top left.  Maybe a little extra ''breathing room'' for the architecture would be nice here :)', '2003-10-14 13:04:24.000000', NULL, 1),
(450007, 42002, 772, '<td valign="top">Nice work... cats on the prowl stalking the prey :)</td>', 'Nice work... cats on the prowl stalking the prey :)', '2003-10-14 13:05:28.000000', NULL, 1),
(450008, 41380, 772, '<td valign="top">This is an interesting composition, but the lighting is a bit too harsh for my taste.  The image also seems to be a bit soft overall.</td>', 'This is an interesting composition, but the lighting is a bit too harsh for my taste.  The image also seems to be a bit soft overall.', '2003-10-14 13:06:08.000000', NULL, 1),
(450010, 41901, 772, '<td valign="top">Interesting progression and story line in the photo.  Are you asking the viewer a question in your title?  Or are you asking yourself if you should have used a different title?  Titles are important parts of the presentation :)</td>', 'Interesting progression and story line in the photo.  Are you asking the viewer a question in your title?  Or are you asking yourself if you should have used a different title?  Titles are important parts of the presentation :)', '2003-10-14 13:07:49.000000', NULL, 1),
(450011, 41923, 772, '<td valign="top">Nice color and presentation.  My personal preference would be more depth of field on this particular photo.  Since all of your subject material is in close quarters, I can''t see any real advantage in trying to isolate a single part of it.</td>', 'Nice color and presentation.  My personal preference would be more depth of field on this particular photo.  Since all of your subject material is in close quarters, I can''t see any real advantage in trying to isolate a single part of it.', '2003-10-14 13:09:17.000000', NULL, 1),
(450016, 41955, 772, '<td valign="top">I like the composition here quite a bit.  I like the ''technology'' photos :)  I also like the lighting here that seems to be harsh.  This photo seems a bit unsharp but appears to have been slightly oversharpened in the process of trying to correct that... maybe.. dunno for sure...</td>', 'I like the composition here quite a bit.  I like the ''technology'' photos :)  I also like the lighting here that seems to be harsh.  This photo seems a bit unsharp but appears to have been slightly oversharpened in the process of trying to correct that... maybe.. dunno for sure...', '2003-10-14 13:12:24.000000', NULL, 1),
(450017, 41172, 772, '<td valign="top">Beautiful composition.  I love the shallow depth of field on this photo.  I think this would make a strong black and white also...</td>', 'Beautiful composition.  I love the shallow depth of field on this photo.  I think this would make a strong black and white also...', '2003-10-14 13:15:54.000000', NULL, 1),
(450030, 41988, 9387, '<td valign="top">I think this photo really meets the challenge and the green against the peanuts is perfect.  The only thing I would have changed is the one peanut that has the string at the end of it.  I found that to be a bit distracting.  Otherwise a great shot.</td>', 'I think this photo really meets the challenge and the green against the peanuts is perfect.  The only thing I would have changed is the one peanut that has the string at the end of it.  I found that to be a bit distracting.  Otherwise a great shot.', '2003-10-14 13:38:00.000000', NULL, 1),
(450031, 41084, 9387, '<td valign="top">This photo meets the challenge perfectly in my opinion as it is obvious.  I like the placement of the chocolate kiss and the way the pull string with the word kiss is seen.  My only negative comment is that it could have been a bit sharper.</td>', 'This photo meets the challenge perfectly in my opinion as it is obvious.  I like the placement of the chocolate kiss and the way the pull string with the word kiss is seen.  My only negative comment is that it could have been a bit sharper.', '2003-10-14 13:39:28.000000', NULL, 1),
(450033, 41576, 9387, '<td valign="top">Great photo and meets the challenge perfectly.  I cannot think of a better idea or photo.</td>', 'Great photo and meets the challenge perfectly.  I cannot think of a better idea or photo.', '2003-10-14 13:40:03.000000', NULL, 1),
(450036, 41966, 9387, '<td valign="top">I like this photo but think it could have been a wee bit better if the inside of the orange was the sharp part instead of the rind.</td>', 'I like this photo but think it could have been a wee bit better if the inside of the orange was the sharp part instead of the rind.', '2003-10-14 13:41:31.000000', NULL, 1),
(450040, 42008, 7086, '<td valign="top">Excellent shot and humour, I''m sure this will inspire many entries if there''s a Halloween challenge. Great positioning, lighting and exposure, what more can I say.</td>', 'Excellent shot and humour, I''m sure this will inspire many entries if there''s a Halloween challenge. Great positioning, lighting and exposure, what more can I say.', '2003-10-14 13:51:14.000000', NULL, 1),
(450073, 41952, 772, '<td valign="top">I think this is a tremendous idea.  This is one of my favorites this week as well.  I love the simplicity and the strength of the color.  I would like to comment on the color though... As I look at this image, I ask myself if the overall presentation would be stronger if you had chosen blue as the surface color instead of yellow.  That would possibly create a stronger contrast for your hand in the upper corner.  It would also possibly make a nice bright yellow dot by having a can of yellow paint being ''exposed'' as well.  Great work... = 10</td>', 'I think this is a tremendous idea.  This is one of my favorites this week as well.  I love the simplicity and the strength of the color.  I would like to comment on the color though... As I look at this image, I ask myself if the overall presentation would be stronger if you had chosen blue as the surface color instead of yellow.  That would possibly create a stronger contrast for your hand in the upper corner.  It would also possibly make a nice bright yellow dot by having a can of yellow paint being ''exposed'' as well.  Great work... = 10', '2003-10-14 14:28:26.000000', NULL, 1),
(450077, 42023, 772, '<td valign="top">Cute idea :)  The text creates more impact that the photo, but the idea is excellent :)</td>', 'Cute idea :)  The text creates more impact that the photo, but the idea is excellent :)', '2003-10-14 14:29:39.000000', NULL, 1),
(450083, 41954, 772, '<td valign="top">This is a bit underexposed.  I''m not sure if correct exposure would improve the overall theme.</td>', 'This is a bit underexposed.  I''m not sure if correct exposure would improve the overall theme.', '2003-10-14 14:31:35.000000', NULL, 1),
(450114, 41041, 772, '<td valign="top">Nice color and detail.</td>', 'Nice color and detail.', '2003-10-14 14:41:44.000000', NULL, 1),
(450118, 41966, 772, '<td valign="top">I like this composition.  My personal opinion is that the overall photo would be stronger if you focused on the detail of the inside of the orange in the reflection rather than the outer skin.</td>', 'I like this composition.  My personal opinion is that the overall photo would be stronger if you focused on the detail of the inside of the orange in the reflection rather than the outer skin.', '2003-10-14 14:42:56.000000', NULL, 1),
(450126, 41532, 772, '<td valign="top">I like the background pottery in this image.  I''m not sure I really understand the purpose in the rest of the image.  I suppose it is showing the ''exposed'' effect by being transparent.  Maybe that is the effect you were going for here.</td>', 'I like the background pottery in this image.  I''m not sure I really understand the purpose in the rest of the image.  I suppose it is showing the ''exposed'' effect by being transparent.  Maybe that is the effect you were going for here.', '2003-10-14 14:45:18.000000', NULL, 1),
(450130, 41791, 772, '<td valign="top">Excellent shot and black and white works very well here.. nice lighting as well.  = 10</td>', 'Excellent shot and black and white works very well here.. nice lighting as well.  = 10', '2003-10-14 14:45:46.000000', NULL, 1),
