(455517, 41958, 6349, '<td valign="top">Wow!  That''s perfect.  A creative and meaningful set-up.  A well deserved ribbon.  Congrats.</td>', 'Wow!  That''s perfect.  A creative and meaningful set-up.  A well deserved ribbon.  Congrats.', '2003-10-20 01:04:12.000000', NULL, 0),
