(455519, 41952, 10848, '<td valign="top">Way to go kiwi! Congratulations! Wonderful work! You deserved this ribbon for sure...again congrats</td>', 'Way to go kiwi! Congratulations! Wonderful work! You deserved this ribbon for sure...again congrats', '2003-10-20 01:04:22.000000', NULL, 0),
(455520, 41952, 10275, '<td valign="top">This shot truly stood out. Big big congrats yet on another blue one!</td>', 'This shot truly stood out. Big big congrats yet on another blue one!', '2003-10-20 01:05:11.000000', NULL, 0),
(455521, 42029, 12448, '<td valign="top">Congrats on third place, a wonderful shot.  Sorry to hear of the poor butterfly''s misfortune.</td>', 'Congrats on third place, a wonderful shot.  Sorry to hear of the poor butterfly''s misfortune.', '2003-10-20 01:05:24.000000', NULL, 0),
(455523, 41958, 10170, '<td valign="top">Very well deserved ribbon indeed :)</td>', 'Very well deserved ribbon indeed :)', '2003-10-20 01:05:51.000000', NULL, 0),
