(455527, 42029, 10275, '<td valign="top">Great shot, well deserved Ribbon. Congrats.</td>', 'Great shot, well deserved Ribbon. Congrats.', '2003-10-20 01:08:03.000000', NULL, 0),
(455528, 41172, 1280, '<td valign="top">yep!  That''s the mystery revealed...Christ in me, the hope of glory!!! For that I am so thankful.<br/>Good job. :-)</td>', 'yep!  That''s the mystery revealed...Christ in me, the hope of glory!!! For that I am so thankful.Good job. :-)', '2003-10-20 01:09:02.000000', NULL, 0),
(455529, 41952, 4380, '<td valign="top">wow! congrats! what im waiting is the result of the science....you''ll get another ribbon for that...all the best...</td>', 'wow! congrats! what im waiting is the result of the science....you''ll get another ribbon for that...all the best...', '2003-10-20 01:10:12.000000', NULL, 0),
(455531, 41952, 9906, '<td valign="top">Yes! (doin'' the happy for kiwi dance!) I picked another ribbon.  My eye must be getting better!!!  LOVE THIS SHOT!<br/> <br/>Congrats on the ribbon Kiwi!  Well deserved!!!<br/>TC<br/><br/><i>Message edited by author 2003-10-20 00:12:35.</i></td>', 'Yes! (doin'' the happy for kiwi dance!) I picked another ribbon.  My eye must be getting better!!!  LOVE THIS SHOT! Congrats on the ribbon Kiwi!  Well deserved!!!TC', '2003-10-20 01:11:51.000000', '2003-10-20 01:12:35.000000', 0),
