(455620, 41730, 6349, '<td valign="top">lol.  this was my favorite interpretation of the challenge.  A great photo too.</td>', 'lol.  this was my favorite interpretation of the challenge.  A great photo too.', '2003-10-20 02:08:00.000000', NULL, 0),
(455621, 41952, 6870, '<td valign="top">Aha! I THOUGHT I recognized that hand! Congrats! Très image d''amusement et pensée bonne hors d''idée !<br/><br/><i>Message edited by author 2003-10-20 01:14:03.</i></td>', 'Aha! I THOUGHT I recognized that hand! Congrats! Très image d''amusement et pensée bonne hors d''idée !', '2003-10-20 02:09:40.000000', '2003-10-20 02:14:03.000000', 0),
