(455625, 42029, 6870, '<td valign="top">Image renversante et ruban bien mérité !</td>', 'Image renversante et ruban bien mérité !', '2003-10-20 02:12:39.000000', NULL, 0),
(455649, 41175, 8860, '<td valign="top">I meant to comment on this during the challenge but ran out of time, Good shot - best of the hard drives. Nice insight to something we all use every day without a second thought. Well composed, nicely lit and the motion was the masterstroke.</td>', 'I meant to comment on this during the challenge but ran out of time, Good shot - best of the hard drives. Nice insight to something we all use every day without a second thought. Well composed, nicely lit and the motion was the masterstroke.', '2003-10-20 02:47:46.000000', NULL, 0),
(455656, 41952, 8860, '<td valign="top">Another one I missed commenting on during the challenge - well done Gary. I''m so glad you''ve got yet another ribbon!<br/> <br/>Goood, strong, dynamic shot - well designed and set-up. My only criticism was that the hand is quite flatly lit (but I know how tough it would be to resolve). Excellent stuff.</td>', 'Another one I missed commenting on during the challenge - well done Gary. I''m so glad you''ve got yet another ribbon! Goood, strong, dynamic shot - well designed and set-up. My only criticism was that the hand is quite flatly lit (but I know how tough it would be to resolve). Excellent stuff.', '2003-10-20 02:53:20.000000', NULL, 0),
(455660, 42029, 2801, '<td valign="top">Another ribbon, YAY! Good job, bebe!! :)</td>', 'Another ribbon, YAY! Good job, bebe!! :)', '2003-10-20 02:56:08.000000', NULL, 0),
(455669, 41952, 9441, '<td valign="top">This was done beautifully.  I knew it would definitely finish tops!  Congratulations on the blue ribbon.  A photo well deserving of it!</td>', 'This was done beautifully.  I knew it would definitely finish tops!  Congratulations on the blue ribbon.  A photo well deserving of it!', '2003-10-20 03:06:13.000000', NULL, 0),
(455680, 42029, 8860, '<td valign="top">Meant to comment during the challenge but I started with my lower votes first and missed it! Excellent capture of a beautiful subject. <br/> <br/>Well done! What''s happened to the butterfly now? Is she a pet or can she not feed? What a shame...</td>', 'Meant to comment during the challenge but I started with my lower votes first and missed it! Excellent capture of a beautiful subject.  Well done! What''s happened to the butterfly now? Is she a pet or can she not feed? What a shame...', '2003-10-20 03:17:22.000000', NULL, 0),
(455707, 41958, 6999, '<td valign="top">I''d love to believe this was opened just to get this photo ... what better reason could there be :-)</td>', 'I''d love to believe this was opened just to get this photo ... what better reason could there be :-)', '2003-10-20 03:38:12.000000', NULL, 0),
(455716, 41874, 6999, '<td valign="top">Interesting that so many people need to know whether or not this is a live fox before giving their score ...</td>', 'Interesting that so many people need to know whether or not this is a live fox before giving their score ...', '2003-10-20 03:42:27.000000', NULL, 0),
(455723, 41952, 2780, '<td valign="top">Congrats gary, your best score yet! :D</td>', 'Congrats gary, your best score yet! :D', '2003-10-20 03:58:56.000000', NULL, 0),
(455730, 41958, 2780, '<td valign="top">Excellent photo, I love the detail and the way the light shines onto the date. Congratulations :)</td>', 'Excellent photo, I love the detail and the way the light shines onto the date. Congratulations :)', '2003-10-20 04:07:36.000000', NULL, 0),
(455736, 41958, 3585, '<td valign="top">Thanks to all taking the time to write on my piture. This was a small half bottle of what had been a great drink last year. Found a small glass to give the impression the bottle was larger. I had to mix liquids to imitate the unique amber color of old Yquem. The light was a hand held 100 watt bulb and socket + the cellar''s ceiling light. This extraordinary sweet wine, if kept in good condition will still be sublime after 150 years in the dark. I still have a few bottle from the beginning of the century that my grandfather bought at the time. unfortunately I cannot afford leaving the same treasure for my grandchildren to come. The prices for this wine have gone totally crazy.</td>', 'Thanks to all taking the time to write on my piture. This was a small half bottle of what had been a great drink last year. Found a small glass to give the impression the bottle was larger. I had to mix liquids to imitate the unique amber color of old Yquem. The light was a hand held 100 watt bulb and socket + the cellar''s ceiling light. This extraordinary sweet wine, if kept in good condition will still be sublime after 150 years in the dark. I still have a few bottle from the beginning of the century that my grandfather bought at the time. unfortunately I cannot afford leaving the same treasure for my grandchildren to come. The prices for this wine have gone totally crazy.', '2003-10-20 04:25:06.000000', NULL, 0),
(455744, 41952, 3585, '<td valign="top">Great idea well executed. Grats</td>', 'Great idea well executed. Grats', '2003-10-20 04:31:28.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(455747, 42029, 3585, '<td valign="top">I also missed the eclosion of the caterpilars form the off-center challenge. They turned out to be huge ugly moths and became the farorite prays for the neighborhood''s cats.<br/>Nicely composed image. congratulations<br/> <br/>JJ</td>', 'I also missed the eclosion of the caterpilars form the off-center challenge. They turned out to be huge ugly moths and became the farorite prays for the neighborhood''s cats.Nicely composed image. congratulations JJ', '2003-10-20 04:39:30.000000', NULL, 0),
(455749, 41952, 6912, '<td valign="top">Congratulations, baby! I knew it would win....great colours and lighting :-) Love from me to my ribbon hunter ......</td>', 'Congratulations, baby! I knew it would win....great colours and lighting :-) Love from me to my ribbon hunter ......', '2003-10-20 04:51:17.000000', NULL, 0),
